// /sitemap.xml — the conventional address many tools check first.
// It's a sitemap index pointing at the real list generated by @astrojs/sitemap (sitemap-0.xml),
// so /sitemap.xml and /sitemap-index.xml both work.
import type { APIRoute } from 'astro';

export const GET: APIRoute = ({ site }) => {
	const base = site ?? new URL('https://www.udaanfoundationsd.org');
	const xml = `<?xml version="1.0" encoding="UTF-8"?><sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><sitemap><loc>${new URL('/sitemap-0.xml', base).href}</loc></sitemap></sitemapindex>`;
	return new Response(xml, { headers: { 'Content-Type': 'application/xml; charset=utf-8' } });
};
